function md_dispatch_orders(){
 $orders=av_read_orders();$workers=av_read_workers();$ordersChanged=false;$workersChanged=false;$now=time();
 foreach($orders as $i=>$o){
  $status=$o['status']??'';
  if($status==='offered'&&!empty($o['assigned_worker_id']))foreach($workers as $wi=>$worker)if(($worker['id']??'')===($o['assigned_worker_id']??'')&&($worker['status']??'')==='online'){$workers[$wi]['status']='reserved';$workersChanged=true;}
  if($status==='searching'&&!empty($o['assigned_worker_id'])&&empty($o['offer_created_at'])){$old=$o['assigned_worker_id'];foreach($workers as $wi=>$worker)if(($worker['id']??'')===$old&&($worker['status']??'')==='reserved'){$workers[$wi]['status']='online';$workersChanged=true;}$orders[$i]['assigned_worker_id']='';$orders[$i]['assigned_worker_name']='';$ordersChanged=true;}
  if($status==='searching'&&!empty($o['assigned_worker_id'])&&!empty($o['offer_created_at'])&&$now-strtotime($o['offer_created_at'])<300){$orders[$i]['status']='offered';$status='offered';$ordersChanged=true;}
  if($status==='offered'&&!empty($o['offer_created_at'])&&$now-strtotime($o['offer_created_at'])>=300){
   $old=$o['assigned_worker_id']??'';
   if(!is_array($orders[$i]['rejected_worker_ids']??null))$orders[$i]['rejected_worker_ids']=array();
   if($old&&!in_array($old,$orders[$i]['rejected_worker_ids'],true))$orders[$i]['rejected_worker_ids'][]=$old;
   foreach($workers as $wi=>$worker)if(($worker['id']??'')===$old&&($worker['status']??'')==='reserved'){$workers[$wi]['status']='online';$workersChanged=true;}
   $orders[$i]['assigned_worker_id']='';$orders[$i]['assigned_worker_name']='';$orders[$i]['offer_created_at']='';$orders[$i]['status']='searching';$status='searching';$ordersChanged=true;
  }
  if($status!=='searching'||!empty($orders[$i]['assigned_worker_id'])||empty($o['lat'])||empty($o['lng']))continue;
  $bestIndex=null;$bestScore=INF;$bestDistance=0;$rejected=$orders[$i]['rejected_worker_ids']??array();
  foreach($workers as $wi=>$candidate){
   if(($candidate['status']??'')!=='online'||empty($candidate['lat'])||empty($candidate['lng'])||in_array($candidate['id']??'',$rejected,true))continue;
   if(empty($candidate['last_seen'])||$now-strtotime($candidate['last_seen'])>180)continue;
   $services=$candidate['services']??array();if($services&&!in_array($o['service']??'',$services,true))continue;
   $distance=av_haversine_km((float)$o['lat'],(float)$o['lng'],(float)$candidate['lat'],(float)$candidate['lng']);
   $candidateScore=$distance-av_worker_rating($candidate['id']??'')*.35;if($candidateScore<$bestScore){$bestScore=$candidateScore;$bestIndex=$wi;$bestDistance=$distance;}
  }
  if($bestIndex!==null){
   $best=$workers[$bestIndex];$orders[$i]['assigned_worker_id']=$best['id'];$orders[$i]['assigned_worker_name']=$best['name']??'';$orders[$i]['worker_rating']=av_worker_rating($best['id']);$orders[$i]['status']='offered';$orders[$i]['offer_created_at']=date('c');$orders[$i]['estimated_arrival_min']=max(1,(int)ceil(($bestDistance/30)*60));$workers[$bestIndex]['status']='reserved';$ordersChanged=true;$workersChanged=true;
  }
 }
 if($ordersChanged)av_write_orders($orders);if($workersChanged)av_write_workers($workers);
}
md_dispatch_orders();
