 if(in_array($effectiveRole,array('superadmin','admin','dispatcher','staff'),true)){$orders=av_read_orders();$partnerOrders=av_partner_orders();}else foreach(av_read_orders() as $o)if(($effectiveRole==='executor'&&$w&&($o['assigned_worker_id']??'')===($w['id']??''))||($effectiveRole==='client'&&($o['user_id']??'')===$u['id']))$orders[]=$o;
}elseif($type==='executor'){
 $w=null;foreach(av_read_workers() as $x)if(($x['id']??'')===$id){$w=$x;break;}if(!$w)av_json_response(array('ok'=>false,'error'=>'AUTH_REQUIRED'),401);if(empty($w['approved'])){$rejected=(($w['review_status']??'')==='rejected');av_json_response(array('ok'=>false,'error'=>$rejected?'Регистрация отклонена: '.($w['rejection_reason']??'Исправьте данные анкеты.'):'Анкета исполнителя ожидает проверки','moderation_status'=>$w['review_status']??'review','rejection_reason'=>$w['rejection_reason']??''),403);}md_reconcile_finance($w['id']);$loyalty=av_worker_loyalty($w);$profile=array('id'=>$w['id'],'name'=>$w['name']??'','phone'=>$w['phone']??'','rating'=>av_worker_rating($w['id']),'role'=>'executor');$executor=array_merge($w,array('rating'=>av_worker_rating($w['id']),'balance'=>av_driver_balance($w['id']),'commission_rate'=>$loyalty['commission_rate'],'payout_rate'=>$loyalty['payout_rate'],'loyalty'=>$loyalty));$finance=av_worker_finance_summary($w['id']);foreach(av_read_orders() as $o)if(($o['assigned_worker_id']??'')===$w['id'])$orders[]=$o;
}elseif($type==='b2b'){$b=null;foreach(av_read_b2b() as $x)if(($x['id']??'')===$id){$b=$x;break;}if(!$b)av_json_response(array('ok'=>false,'error'=>'AUTH_REQUIRED'),401);$profile=array('id'=>$b['id'],'name'=>$b['company']??$b['contact']??'B2B','phone'=>$b['phone']??'','rating'=>5,'role'=>'b2b');foreach(av_read_orders() as $o)if(($o['b2b_id']??'')===$b['id'])$orders[]=$o;
